import { test } from "node:test";
import assert from "node:assert/strict";
import { MemoryBlobStore, type BlobStore } from "../src/storage/blobStore.ts";
import { ObjectStorageBlobStore, type ObjectStorageClient } from "../src/storage/objectStorageBlobStore.ts";
import { CachedBlobStore } from "../src/storage/cachedBlobStore.ts";
import { getOrCreateAvatar, removeAvatar, uploadAvatar } from "../src/avatars.ts";
import { loadAttachment, saveAttachment } from "../src/attachments.ts";

const sdkError = (code: string) => Object.assign(new Error(code), { code });

// Fake SDK: a map of objects, plus a switch to make reads fail like the real service can
// (reads go to a different, busier endpoint than writes).
function fakeClient() {
    const objects = new Map<string, Uint8Array>();
    let readOutage: string | null = null;
    const calls = { get: 0, put: 0 };
    const client: ObjectStorageClient = {
        async getObject(bucket, key) {
            calls.get++;
            if (readOutage) throw sdkError(readOutage);
            const body = objects.get(`${bucket}/${key}`);
            if (!body) throw sdkError("NoSuchKey");
            return body;
        },
        async putObject(bucket, key, body) {
            calls.put++;
            objects.set(`${bucket}/${key}`, body);
        },
        async deleteObject(bucket, key) {
            if (!objects.delete(`${bucket}/${key}`)) throw sdkError("NoSuchKey");
        },
    };
    return { client, objects, calls, fail: (code: string | null) => (readOutage = code) };
}

// The same contract test runs against every implementation.
test("every BlobStore: round trip, missing keys are null, deleting twice is fine", async () => {
    const implementations: [string, BlobStore][] = [
        ["MemoryBlobStore", new MemoryBlobStore()],
        ["ObjectStorageBlobStore", new ObjectStorageBlobStore(fakeClient().client, "media", "prod/")],
        ["CachedBlobStore", new CachedBlobStore(new MemoryBlobStore())],
    ];
    for (const [name, store] of implementations) {
        await store.put("a.txt", Buffer.from("hello"));
        assert.equal((await store.get("a.txt"))?.toString(), "hello", name);
        assert.equal(await store.get("missing.txt"), null, name);
        await store.delete("a.txt");
        await store.delete("a.txt");
        assert.equal(await store.get("a.txt"), null, name);
    }
});

test("ObjectStorageBlobStore: failures other than a missing key reject", async () => {
    const fake = fakeClient();
    const store = new ObjectStorageBlobStore(fake.client, "media");
    await store.put("a.txt", Buffer.from("hello"));
    fake.fail("AccessDenied");
    await assert.rejects(store.get("a.txt"), /AccessDenied/);
    fake.fail("RequestTimeout");
    await assert.rejects(store.get("a.txt"), /RequestTimeout/);
});

test("a storage timeout doesn't replace an uploaded avatar with a generated one", async () => {
    const fake = fakeClient();
    const store = new ObjectStorageBlobStore(fake.client, "media");
    await store.put("avatars/u1.png", Buffer.from("uploaded-photo"));

    fake.fail("RequestTimeout");
    await assert.rejects(getOrCreateAvatar(store, "u1", () => Buffer.from("initials-UA")));

    fake.fail(null);
    const avatar = await store.get("avatars/u1.png");
    console.log("stored avatar after the outage:", avatar?.toString());
    assert.equal(avatar?.toString(), "uploaded-photo");
});

test("avatars: generated once on first visit, replaced by uploads, regenerated after removal", async () => {
    const store = new MemoryBlobStore();
    let renders = 0;
    const render = () => (renders++, Buffer.from("initials-NV"));
    assert.equal((await getOrCreateAvatar(store, "new", render)).toString(), "initials-NV");
    assert.equal((await getOrCreateAvatar(store, "new", render)).toString(), "initials-NV");
    assert.equal(renders, 1);

    const png = Buffer.concat([Buffer.from([0x89, 0x50, 0x4e, 0x47]), Buffer.from("rest-of-png")]);
    await uploadAvatar(store, "new", png);
    assert.ok((await getOrCreateAvatar(store, "new", render)).equals(png));
    await assert.rejects(uploadAvatar(store, "new", Buffer.from("GIF89a")), /PNG/);

    await removeAvatar(store, "new");
    await removeAvatar(store, "new");
    assert.equal((await getOrCreateAvatar(store, "new", render)).toString(), "initials-NV");
    assert.equal(renders, 2);
});

test("the cache serves repeat reads, evicts the least recently used, and forgets deleted keys", async () => {
    const fake = fakeClient();
    const cached = new CachedBlobStore(new ObjectStorageBlobStore(fake.client, "media"), 2);
    for (const k of ["a", "b", "c"]) await cached.put(k, Buffer.from(k));
    assert.equal(cached.size, 2);
    const before = fake.calls.get;
    assert.equal((await cached.get("c"))?.toString(), "c");
    assert.equal(fake.calls.get, before);
    assert.equal((await cached.get("a"))?.toString(), "a");
    assert.equal(fake.calls.get, before + 1);
    await cached.delete("a");
    assert.equal(await cached.get("a"), null);
});

test("an outage behind the cache rejects instead of looking like a missing blob", async () => {
    const fake = fakeClient();
    const cached = new CachedBlobStore(new ObjectStorageBlobStore(fake.client, "media"));
    await fake.client.putObject("media", "avatars/u2.png", Buffer.from("photo"));
    fake.fail("SlowDown");
    await assert.rejects(cached.get("avatars/u2.png"), /SlowDown/);
});

test("identical attachments are stored once and read back by id", async () => {
    const fake = fakeClient();
    const store = new ObjectStorageBlobStore(fake.client, "tickets");
    const a = await saveAttachment(store, "crash.log", Buffer.from("stack trace"));
    const b = await saveAttachment(store, "crash (1).log", Buffer.from("stack trace"));
    assert.equal(a.id, b.id);
    assert.equal(fake.calls.put, 1);
    assert.equal((await loadAttachment(store, a.id))?.toString(), "stack trace");
    assert.equal(await loadAttachment(store, "../../etc/passwd"), null);
    await assert.rejects(saveAttachment(store, "empty.txt", Buffer.alloc(0)));
});

test("an attachment upload during a read outage fails instead of silently re-uploading", async () => {
    const fake = fakeClient();
    const store = new ObjectStorageBlobStore(fake.client, "tickets");
    await saveAttachment(store, "a.png", Buffer.from("png-bytes"));
    fake.fail("RequestTimeout");
    await assert.rejects(saveAttachment(store, "a-again.png", Buffer.from("png-bytes")), /RequestTimeout/);
    assert.equal(fake.calls.put, 1);
});
